func init() {
	artifactCommands["export"] = artifactExchangeExportCommand
	artifactCommands["import"] = artifactExchangeImportCommand
	artifactCommands["inspect"] = artifactExchangeInspectCommand
}

func init() {
	artifactCommands["list"] = cmdArtifactList
	artifactCommands["help"] = cmdArtifactHelp
	artifactCommands["--help"] = cmdArtifactHelp
}

func init() {
	artifactCommands["fetch"] = func(args []string) error { return artifactGitCommand("fetch", args) }
	artifactCommands["push"] = func(args []string) error { return artifactGitCommand("push", args) }
}

func init() {
	artifactCommands["revise"] = func(args []string) error { return artifactSuccessorCommand("record.revise", args) }
	artifactCommands["resolve"] = func(args []string) error { return artifactSuccessorCommand("record.resolve", args) }
	artifactCommands["convert"] = func(args []string) error { return artifactSuccessorCommand("record.convert", args) }
	for _, mode := range []string{"show", "heads", "history"} {
		artifactCommands[mode] = func(args []string) error { return artifactCatalogCommand(mode, args) }
	}
}

func init() {
	artifactCommands["type"] = cmdArtifactType
	artifactCommands["schema"] = cmdArtifactSchema
	artifactCommands["record"] = cmdArtifactRecord
}

func init() {
	artifactCommands["search"] = cmdArtifactSearch
	artifactCommands["help"] = cmdArtifactSearchHelp
	artifactCommands["--help"] = cmdArtifactSearchHelp
}

func init() {
	artifactTypeCommands["publish"] = cmdArtifactTypePublish
	artifactTypeCommands["show"] = cmdArtifactTypeShow
	artifactCommands["open"] = cmdArtifactOpen
}

func init() {
	for _, method := range []string{"artifact.read", "artifact.search", "artifact.type.read", "artifact.mutate", "artifact.type.publish", "artifact.operation"} {
		extensionHostMethods[method] = extensionArtifactDispatch
	}
}

func init() {
	for _, method := range []string{"changes.capture", "changes.page", "changes.since"} {
		extensionHostMethods[method] = extensionChangesDispatch
	}
}

func init() {
	for _, method := range []string{"identity.public", "resource.read", "resource.mutate", "resource.operation"} {
		extensionHostMethods[method] = extensionNativeDispatch
	}
}
